public void testIndexedArray_2_oe() {
    Iterator<E> iter = makeArrayIterator(testArray, 2);
    int count = 0;
    while (iter.hasNext()) {
        ++count;
        iter.next();
    }


    iter = makeArrayIterator(testArray, 1, testArray.length - 1);
    count = 0;
    while (iter.hasNext()) {
        ++count;
        iter.next();
    }

    assertEquals(0, count);
}

