    final Map<K, V> map = getMap();


    final Iterator<K> it2 = map.keySet().iterator();
    final List<K> list = new ArrayList<>();
    while (it.hasNext()) {
        final K key = it.next();
        list.add(key);
    }
    while (it.hasPrevious()) {
