public void testCollectionIteratorRemove_4_oe() {
    if (!isRemoveSupported()) {
        return;
    }

    resetEmpty();
    try {
        getCollection().iterator().remove();
    } catch (final IllegalStateException e) {
    }
    verify();

    try {
        final Iterator<E> iter = getCollection().iterator();
        iter.hasNext();
        iter.remove();
    } catch (final IllegalStateException e) {
    }
    verify();

    resetFull();
    int size = getCollection().size();
    Iterator<E> iter = getCollection().iterator();
    while (iter.hasNext()) {
        Object o = iter.next();
        if (o instanceof Map.Entry) {
            o = cloneMapEntry((Map.Entry<E, E>) o);
        }
        iter.remove();

        if (!areEqualElementsDistinguishable()) {
            getConfirmed().remove(o);
            verify();
        }

        size--;
    }
    assertEquals(false, iter.hasNext());
}

