        resetEmpty();
        final boolean r = getCollection().offer(element);
        getConfirmed().add(element);
        verify();
    }

    resetEmpty();
    int size = 0;
    for (final E element : elements) {
        final boolean r = getCollection().offer(element);
        getConfirmed().add(element);
        verify();
