public void testAddNodeAfter_1_oe() {
    resetEmpty();
    final AbstractLinkedList<E> list = getCollection();
    if (!isAddSupported()) {
        try {
            list.addFirst(null);
        } catch (final UnsupportedOperationException ex) {}
    }

    list.addFirst((E) "value1");
    list.addNodeAfter(list.getNode(0, false), (E) "value2");
