public void testListAddIndexed_14_oe() {
    final ListOrderedSet<E> set = makeObject();
    set.add((E) ZERO);
    set.add((E) TWO);

    set.add(1, (E) ONE);

    set.add(0, (E) ONE);

    final List<E> list = new ArrayList<>();
    list.add((E) ZERO);
    list.add((E) TWO);

    set.addAll(0, list);

    list.add(0, (E) THREE); // list = [3,0,2]
    set.remove(TWO);    //  set = [0,1]
    set.addAll(1, list);
    assertEquals(ONE, set.get(0));
}

