    } catch (final IndexOutOfBoundsException ex) {}

    resetFull();
    lm = getMap();
    try {
        lm.getValue(-1);
    } catch (final IndexOutOfBoundsException ex) {}
    try {
        lm.getValue(lm.size());
    } catch (final IndexOutOfBoundsException ex) {}

    int i = 0;
    for (final MapIterator<K, V> it = lm.mapIterator(); it.hasNext(); i++) {
        it.next();
        assertEquals(false, lm.isEmpty());
}
}

